package ethtypes

import (
	"bytes"
	"testing"

	"github.com/sig-0/ethrlp"
	ethProto "github.com/sig-0/ethtypes/proto/eth/v1"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestReceiptVectors(t *testing.T) {
	t.Parallel()

	// Mainnet block 46147, post state of tx 0x5c504ed432cb51138bcf09aa5e8a410dd4a1e204ef84bfed1be16dfba1b22060
	r1PostState := StringToHash("0x96a8e009d2b88b1483e6941e6812e32263b05683fac202abc622a3e31aed1957")

	// Each raw receipt is from a mainnet block whose receipts root it reproduces
	testTable := []struct {
		postState         *Hash
		log               *Log
		name              string
		raw               string
		cumulativeGasUsed uint64
		receiptType       byte
		status            bool
	}{
		{
			// Mainnet block 46147, tx 0x5c504ed432cb51138bcf09aa5e8a410dd4a1e204ef84bfed1be16dfba1b22060 (pre-Byzantium post state, EIP-658)
			name:              "pre-Byzantium",
			raw:               "",
			postState:         &r1PostState,
			cumulativeGasUsed: 21000,
		},
		{
			// Mainnet block 17034954, tx 0xef96b9b48a5b1419792af9cdbee9d9f60e7e89681cc6fa726af5ef7ae66025e2
			name:              "legacy with a log",
			raw:               "",
			status:            true,
			cumulativeGasUsed: 149664,
			log: &Log{
				Address: StringToAddress("0x7d1afa7b718fb893db30a3abc0cfc608aacfebb0"),
				Topics: []Hash{
					StringToHash("0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef"),
					StringToHash("0x000000000000000000000000f93b8955ad543f6319789f7b8ecc693d9fc495d0"),
					StringToHash("0x00000000000000000000000094c642fe0a4a6b0a993e4024ab8fd634a6f06de4"),
				},
				Data: hexBytes(t, "0x0000000000000000000000000000000000000000000000001bc16d674ec80000"),
			},
		},
		{
			// Mainnet block 17034954, tx 0x9c8b43f8b217d63b2e7ce1586a6b1daf6e1d251d7fcc0ef046320c95a0b11c31
			name:              "type 1",
			raw:               "",
			receiptType:       Transaction2930,
			status:            true,
			cumulativeGasUsed: 690704,
		},
		{
			// Mainnet block 17034954, tx 0xa775e81d9d7b0cbf56cb865b9221f85599098fa5486c935644e829778c1f024f
			name:              "type 2 success",
			raw:               "",
			receiptType:       Transaction1559,
			status:            true,
			cumulativeGasUsed: 170664,
		},
		{
			// Mainnet block 17034954, tx 0xbde4fb0cc69f4e0eec4b559a8dd888af26f213717bba65cc440651621e5e047e
			name:              "type 2 failed",
			raw:               "",
			receiptType:       Transaction1559,
			cumulativeGasUsed: 397814,
		},
		{
			// Mainnet block 19426589, tx 0x9c1fbda4f649ac806ab0faefbe94e1a60282eb374ead6aa01bac042f52b28a8c
			name:              "type 3",
			raw:               "",
			receiptType:       Transaction4844,
			status:            true,
			cumulativeGasUsed: 5681700,
		},
		{
			// Mainnet block 23068673, tx 0xb99d94de6d9d1d35b597901455e603ca5d2861f995f3492c6bb875299ab754ac
			name:              "type 4 with a log",
			raw:               "",
			receiptType:       Transaction7702,
			status:            true,
			cumulativeGasUsed: 18490347,
			log: &Log{
				Address: StringToAddress("0xa0b86991c6218b36c1d19d4a2e9eb0ce3606eb48"),
				Topics: []Hash{
					StringToHash("0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef"),
					StringToHash("0x0000000000000000000000002228e5704b637131a3798a186caf18366c146f74"),
					StringToHash("0x000000000000000000000000a030779804c096635c17126b7676a4b5fffbfb65"),
				},
				Data: hexBytes(t, "0x0000000000000000000000000000000000000000000000000000001a9b2cd705"),
			},
		},
	}

	for _, testCase := range testTable {
		t.Run(testCase.name, func(t *testing.T) {
			t.Parallel()

			raw := hexBytes(t, testCase.raw)

			var receipt Receipt

			require.NoError(t, receipt.FromRLP(raw))

			assert.Equal(t, testCase.receiptType, receipt.Type)
			assert.Equal(t, testCase.status, receipt.Status)
			assert.Equal(t, testCase.cumulativeGasUsed, receipt.CumulativeGasUsed)
			assert.Equal(t, testCase.postState, receipt.PostState)

			if testCase.log == nil {
				assert.Empty(t, receipt.Logs)
			} else {
				require.Len(t, receipt.Logs, 1)
				assert.Equal(t, testCase.log.ToRLP(), receipt.Logs[0].ToRLP())

				var log Log

				require.NoError(t, log.FromRLP(testCase.log.ToRLP()))
				assert.Equal(t, testCase.log.ToRLP(), log.ToRLP())
			}

			assert.Equal(t, raw, receipt.ToRLP())

			var fromProto Receipt

			require.NoError(t, fromProto.FromProto(receipt.ToProto()))
			assert.Equal(t, raw, fromProto.ToRLP())
		})
	}
}

func TestReceiptFromRLPRejects(t *testing.T) {
	t.Parallel()

	address := ethrlp.EncodeBytes(make([]byte, addressSize))
	log := &Log{Topics: []Hash{{0x01}}, Data: []byte{0xaa}}

	// withItems encodes a receipt list with items replaced at their index
	withItems := func(items map[int][]byte) []byte {
		fields := [][]byte{
			ethrlp.EncodeBool(true),
			ethrlp.EncodeUint(100),
			ethrlp.EncodeBytes(make([]byte, BloomByteLength)),
			ethrlp.EncodeArray([][]byte{log.ToRLP()}),
		}

		for i, item := range items {
			fields[i] = item
		}

		return ethrlp.EncodeArray(fields)
	}

	valid := withItems(nil)

	testTable := []struct {
		wantErr error
		name    string
		bad     []byte
	}{
		{name: "nil", bad: nil, wantErr: ethrlp.ErrInvalidLength},
		{name: "empty", bad: []byte{}, wantErr: ethrlp.ErrInvalidLength},
		{name: "type 0 prefix", bad: append([]byte{TransactionLegacy}, valid...), wantErr: ErrInvalidReceiptType},
		{name: "status 2", bad: withItems(map[int][]byte{0: ethrlp.EncodeUint(2)}), wantErr: ErrInvalidReceiptRLPStatus},
		{name: "31-byte first item", bad: withItems(map[int][]byte{0: ethrlp.EncodeBytes(make([]byte, 31))}), wantErr: ErrInvalidReceiptRLPStatus},
		{name: "3 items", bad: ethrlp.EncodeArray([][]byte{ethrlp.EncodeBool(true), ethrlp.EncodeUint(1), ethrlp.EncodeArray(nil)})},
		{name: "5 items", bad: ethrlp.EncodeArray([][]byte{ethrlp.EncodeBool(true), ethrlp.EncodeUint(1), ethrlp.EncodeBytes(make([]byte, BloomByteLength)), ethrlp.EncodeArray(nil), ethrlp.EncodeArray(nil)})},
		{name: "255-byte bloom", bad: withItems(map[int][]byte{2: ethrlp.EncodeBytes(make([]byte, BloomByteLength-1))}), wantErr: ErrInvalidReceiptRLPLogsBloom},
		{
			name:    "log with 2 items",
			bad:     withItems(map[int][]byte{3: ethrlp.EncodeArray([][]byte{ethrlp.EncodeArray([][]byte{address, ethrlp.EncodeArray(nil)})})}),
			wantErr: ErrInvalidReceiptRLPLogs,
		},
		{
			name: "31-byte topic",
			bad: withItems(map[int][]byte{3: ethrlp.EncodeArray([][]byte{ethrlp.EncodeArray([][]byte{
				address,
				ethrlp.EncodeArray([][]byte{ethrlp.EncodeBytes(make([]byte, 31))}),
				ethrlp.EncodeBytes(nil),
			})})}),
			wantErr: ErrInvalidLogRLPTopics,
		},
		{name: "trailing byte", bad: append(bytes.Clone(valid), 0x00), wantErr: ethrlp.ErrTrailingBytes},
	}

	for _, testCase := range testTable {
		t.Run(testCase.name, func(t *testing.T) {
			t.Parallel()

			assertDecodeRejects[Receipt](t, valid, testCase.bad)

			if testCase.wantErr != nil {
				assert.ErrorIs(t, (&Receipt{}).FromRLP(testCase.bad), testCase.wantErr)
			}
		})
	}

	t.Run("Log.FromRLP with 2 items", func(t *testing.T) {
		t.Parallel()

		assertDecodeRejects[Log](t, log.ToRLP(), ethrlp.EncodeArray([][]byte{address, ethrlp.EncodeArray(nil)}))
	})
}

func TestReceiptProto(t *testing.T) {
	t.Parallel()

	t.Run("every field", func(t *testing.T) {
		t.Parallel()

		postState := Hash{0x01}
		log := &Log{Address: Address{0x03}, Topics: []Hash{{0x04}}, Data: []byte{0x05}}
		receipt := &Receipt{
			Logs:              []*Log{log},
			PostState:         &postState,
			LogsBloom:         Bloom{0x06},
			CumulativeGasUsed: 21000,
			Type:              Transaction4844,
			Status:            true,
		}

		var decoded Receipt

		require.NoError(t, decoded.FromProto(receipt.ToProto()))

		require.Len(t, decoded.Logs, 1)
		assert.Equal(t, log.ToRLP(), decoded.Logs[0].ToRLP())
		assert.Equal(t, receipt.PostState, decoded.PostState)
		assert.Equal(t, receipt.LogsBloom, decoded.LogsBloom)
		assert.Equal(t, receipt.CumulativeGasUsed, decoded.CumulativeGasUsed)
		assert.Equal(t, receipt.Type, decoded.Type)
		assert.Equal(t, receipt.Status, decoded.Status)
	})

	t.Run("nil pointers", func(t *testing.T) {
		t.Parallel()

		var decoded Receipt

		require.NoError(t, decoded.FromProto((&Receipt{CumulativeGasUsed: 1}).ToProto()))

		assert.Nil(t, decoded.PostState)
		assert.Nil(t, decoded.Logs)
	})

	t.Run("overwrites the receiver", func(t *testing.T) {
		t.Parallel()

		postState := Hash{0x01}
		receipt := Receipt{
			Logs:      []*Log{{}},
			PostState: &postState,
			Status:    true,
		}

		require.NoError(t, receipt.FromProto(&ethProto.Receipt{CumulativeGasUsed: 5}))

		assert.Nil(t, receipt.Logs)
		assert.Nil(t, receipt.PostState)
		assert.False(t, receipt.Status)
		assert.Equal(t, uint64(5), receipt.CumulativeGasUsed)
	})

	t.Run("errors", func(t *testing.T) {
		t.Parallel()

		receipt := Receipt{CumulativeGasUsed: 1}

		assert.ErrorIs(t, receipt.FromProto(nil), ErrNilProtoReceipt)
		assert.ErrorIs(t, receipt.FromProto(&ethProto.Receipt{Logs: []*ethProto.Log{nil}}), ErrNilProtoLog)
		assert.ErrorIs(t, receipt.FromProto(&ethProto.Receipt{Type: 0x80}), ErrInvalidReceiptType)
		assert.Equal(t, uint64(1), receipt.CumulativeGasUsed)
		assert.Nil(t, receipt.Logs)
	})

	t.Run("log", func(t *testing.T) {
		t.Parallel()

		var log Log

		require.NoError(t, log.FromProto(&ethProto.Log{
			Address: Address{0x01}.ToBytes(),
			Topics:  [][]byte{Hash{0x02}.ToBytes()},
			Data:    []byte{0x03},
		}))

		assert.Equal(t, Address{0x01}, log.Address)
		assert.Equal(t, []Hash{{0x02}}, log.Topics)
		assert.Equal(t, []byte{0x03}, log.Data)
		assert.ErrorIs(t, log.FromProto(nil), ErrNilProtoLog)
	})
}

func FuzzReceiptFromRLP(f *testing.F) {
	for _, seed := range []string{
		// Mainnet block 46147, pre-Byzantium receipt (EIP-658)
		"",
		// Mainnet block 17034954, legacy receipt with a log
		"",
		// Mainnet block 17034954, type 1 receipt
		"",
		// Mainnet block 17034954, type 2 receipt
		"",
		// Mainnet block 17034954, failed type 2 receipt
		"",
		// Mainnet block 19426589, type 3 receipt
		"",
		// Mainnet block 23068673, type 4 receipt with a log
		"",
		// Invalid: type 0 prefix
		"0x00c0",
		// Invalid: 3 items
		"0xc3018080",
	} {
		f.Add(hexBytes(f, seed))
	}

	f.Fuzz(func(t *testing.T, data []byte) {
		var receipt Receipt
		if receipt.FromRLP(data) == nil {
			assert.Equal(t, data, receipt.ToRLP())
		}
	})
}
